def test_topological_sort_tasks_basic():
    """Test the basic example from the specification."""
    dependencies = {'deploy': ['build', 'test'], 'build': [], 'test': ['build']}
    result = topological_sort_tasks(dependencies)
    assert result == ['build', 'test', 'deploy']

def test_topological_sort_tasks_empty():
    """Test with empty dependencies."""
    dependencies = {}
    result = topological_sort_tasks(dependencies)
    assert result == []

def test_topological_sort_tasks_single_task():
    """Test with a single task with no prerequisites."""
    dependencies = {'task1': []}
    result = topological_sort_tasks(dependencies)
    assert result == ['task1']

def test_topological_sort_tasks_cycle():
    """Test that circular dependencies return None."""
    dependencies = {'a': ['b'], 'b': ['a']}
    result = topological_sort_tasks(dependencies)
    assert result is None

def test_topological_sort_tasks_diamond():
    """Test diamond dependency pattern with alphabetical tie-breaking."""
    # d depends on b and c, b and c depend on a
    dependencies = {'a': [], 'b': ['a'], 'c': ['a'], 'd': ['b', 'c']}
    result = topological_sort_tasks(dependencies)
    assert result == ['a', 'b', 'c', 'd']

def test_topological_sort_tasks_multiple_independent():
    """Test multiple independent tasks with alphabetical ordering."""
    dependencies = {'z': [], 'a': [], 'm': []}
    result = topological_sort_tasks(dependencies)
    assert result == ['a', 'm', 'z']

