def test_flatten_nested_dict():
    result = flatten_nested_dict({'a': {'b': 1, 'c': {'d': 2}}, 'e': 3})
    assert result == {'a.b': 1, 'a.c.d': 2, 'e': 3}
    result = flatten_nested_dict({'a': {'b': {}, 'c': 1}, 'd': 2})
    assert result == {'a.b': {}, 'a.c': 1, 'd': 2}
    result = flatten_nested_dict({})
    assert result == {}
    result = flatten_nested_dict({'a': {'b': 1, 'c': {'d': 2}}, 'e': 3}, sep='/')
    assert result == {'a/b': 1, 'a/c/d': 2, 'e': 3}
    result = flatten_nested_dict({'a': {'b': {'c': {'d': 4}}}})
    assert result == {'a.b.c.d': 4}
    result = flatten_nested_dict({'a': {}, 'b': {'c': {}}})
    assert result == {'a': {}, 'b.c': {}}
test_flatten_nested_dict()

