def test_flatten_nested_dict():
    from typing import Dict, Any

    def flatten_nested_dict(d: Dict[str, Any], sep: str = '.') -> Dict[str, Any]:
        result = {}
        for key, value in d.items():
            if isinstance(value, dict):
                if not value:
                    result[key] = value
                else:
                    for sub_key, sub_value in flatten_nested_dict(value, sep).items():
                        result[f"{key}{sep}{sub_key}"] = sub_value
            else:
                result[key] = value
        return result

    # Test 1: Basic nested dictionary
    assert flatten_nested_dict({'a': {'b': 1, 'c': {'d': 2}}, 'e': 3}) == {'a.b': 1, 'a.c.d': 2, 'e': 3}

    # Test 2: Empty dictionary at leaf node is preserved
    assert flatten_nested_dict({'a': {'b': {}}, 'c': 1}) == {'a.b': {}, 'c': 1}

    # Test 3: Custom separator
    assert flatten_nested_dict({'a': {'b': 1}}, sep='-') == {'a-b': 1}

    # Test 4: Empty input dictionary
    assert flatten_nested_dict({}) == {}

    # Test 5: Single level dictionary (no nesting)
    assert flatten_nested_dict({'a': 1, 'b': 2}) == {'a': 1, 'b': 2}

    # Test 6: Deeply nested dictionary
    assert flatten_nested_dict({'a': {'b': {'c': {'d': 1}}}}) == {'a.b.c.d': 1}

test_flatten_nested_dict()

