from typing import List

def parse_csv_line_with_quotes(line: str, delimiter: str = ',') -> List[str]:
    """
    Parse a single CSV row supporting double-quote escaping and embedded delimiters.
    Rules:
    - Fields separated by delimiter.
    - Fields enclosed in double quotes can contain the delimiter and escaped quotes (represented as '""').
    - Enclosing quotes are stripped from the resulting field.
    - Returns list of field strings with whitespace preserved.
    Example: '1,"Smith, John","""Hero"""' -> ['1', 'Smith, John', '"Hero"']
    """
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            fields.append(''.join(field))
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != delimiter:
                field.append(line[i])
                i += 1
            fields.append(''.join(field))

        # Skip delimiter
        if i < n and line[i] == delimiter:
            i += 1

    return fields

