def test_topological_sort_tasks():
    # Test 1: Example from specification
    deps = {'deploy': ['build', 'test'], 'build': [], 'test': ['build']}
    assert topological_sort_tasks(deps) == ['build', 'test', 'deploy']

    # Test 2: No dependencies (all independent tasks) -> alphabetical order
    deps = {'b': [], 'a': [], 'c': []}
    assert topological_sort_tasks(deps) == ['a', 'b', 'c']

    # Test 3: Chain of dependencies
    deps = {'c': ['b'], 'b': ['a'], 'a': []}
    assert topological_sort_tasks(deps) == ['a', 'b', 'c']

    # Test 4: Circular dependency returns None
    deps = {'a': ['b'], 'b': ['a']}
    assert topological_sort_tasks(deps) is None

    # Test 5: Single task with no dependencies
    deps = {'task1': []}
    assert topological_sort_tasks(deps) == ['task1']

    # Test 6: Multiple valid orders, tie broken alphabetically
    # 'b' and 'd' both depend on 'a', 'c' depends on 'b'
    # After 'a', both 'b' and 'd' are available; 'b' comes first alphabetically
    deps = {'a': [], 'b': ['a'], 'd': ['a'], 'c': ['b']}
    # After a: available = {b, d}. Pick b. Then c becomes available. Available = {c, d}. Pick c. Then d.
    assert topological_sort_tasks(deps) == ['a', 'b', 'c', 'd']

    # Test 7: Empty input
    deps = {}
    assert topological_sort_tasks(deps) == []

