def validate_balanced_parentheses(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

assert validate_balanced_parentheses('a(b[c]d)e') == True
assert validate_balanced_parentheses('([)]') == False
assert validate_balanced_parentheses('{{}')) == False
assert validate_balanced_parentheses('') == True
assert validate_balanced_parentheses('abc') == True
assert validate_balanced_parentheses('((()))') == True

