    deps1 = {'c': ['b'], 'b': ['a'], 'a': []}
    assert topological_sort_tasks(deps1) == ['a', 'b', 'c']

    # Test 2: Multiple independent tasks, alphabetical tie-breaking
    deps2 = {'task_b': [], 'task_a': [], 'task_c': []}
    assert topological_sort_tasks(deps2) == ['task_a', 'task_b', 'task_c']

    # Test 3: Diamond dependency
    deps3 = {'d': ['b', 'c'], 'b': ['a'], 'c': ['a'], 'a': []}
    result = topological_sort_tasks(deps3)
    assert result is not None
    # 'a' must come first, then 'b' and 'c' in alphabetical order, then 'd'
    assert result == ['a', 'b', 'c', 'd']

    # Test 4: Circular dependency returns None
    deps4 = {'a': ['b'], 'b': ['c'], 'c': ['a']}
    assert topological_sort_tasks(deps4) is None

    # Test 5: Empty dependencies dict
    deps5 = {}
    assert topological_sort_tasks(deps5) == []

    # Test 6: Example from spec
    deps6 = {'deploy': ['build', 'test'], 'build': [], 'test': ['build']}
    assert topological_sort_tasks(deps6) == ['build', 'test', 'deploy']

