def test_parse_semver():
    assert parse_semver('1.2.3') == {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': None, 'build': None}
    assert parse_semver('1.2.3-alpha.1+build.001') == {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': 'alpha.1', 'build': 'build.001'}
    assert parse_semver('01.2.3') is None
    assert parse_semver('1.02.3') is None
    assert parse_semver('1.2.03') is None
    assert parse_semver('0.0.0') == {'major': 0, 'minor': 0, 'patch': 0, 'prerelease': None, 'build': None}
    assert parse_semver('1.2') is None
    assert parse_semver('1.2.3.4') is None
    assert parse_semver('-1.2.3') is None
    assert parse_semver('1.2.3-alpha..1') is None
    assert parse_semver('0.0.1-alpha') == {'major': 0, 'minor': 0, 'patch': 1, 'prerelease': 'alpha', 'build': None}
test_parse_semver()

