def test_flatten_nested_dict():
    # Import the function under test
    from flatten_nested_dict import flatten_nested_dict

    # Test 1: Basic nested dictionary
    d1 = {'a': {'b': 1, 'c': {'d': 2}}, 'e': 3}
    expected1 = {'a.b': 1, 'a.c.d': 2, 'e': 3}
    assert flatten_nested_dict(d1) == expected1

    # Test 2: Custom separator
    d2 = {'a': {'b': 1}}
    expected2 = {'a/b': 1}
    assert flatten_nested_dict(d2, sep='/') == expected2

    # Test 3: Empty dictionary
    d3 = {}
    expected3 = {}
    assert flatten_nested_dict(d3) == expected3

    # Test 4: Empty dict at leaf node is preserved
    d4 = {'a': {}}
    expected4 = {'a': {}}
    assert flatten_nested_dict(d4) == expected4

    # Test 5: Deeper nesting
    d5 = {'a': {'b': {'c': {'d': 4}}}}
    expected5 = {'a.b.c.d': 4}
    assert flatten_nested_dict(d5) == expected5

    # Test 6: Multiple levels and mixed values
    d6 = {'x': 1, 'y': {'z': {'w': 2}}, 'v': {'u': 3}}
    expected6 = {'x': 1, 'y.z.w': 2, 'v.u': 3}
    assert flatten_nested_dict(d6) == expected6

test_flatten_nested_dict()

