from typing import Optional, Dict, Any

def test_parse_semver():
    assert parse_semver('1.2.3') == {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': None, 'build': None}
    result = parse_semver('1.2.3-alpha.1+build.001')
    assert parse_semver('1.2.3') == {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': None, 'build': None}
    expected = {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': 'alpha.1', 'build': None}
    assert parse_semver('1.2.3-alpha.1') == expected
    expected = {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': None, 'build': 'build.001'}
    assert parse_semver('1.2.3+build.001') == expected
    expected = {'major': 1, 'minor': 2, 'patch': 3, 'prerelease': 'alpha.1', 'build': 'build.001'}
    assert parse_semver('1.2.3-alpha.1+build.001') == expected
    assert parse_semver('01.2.3') is None
    assert parse_semver('a.b.c') is None
    assert parse_semver('1.2') is None
test_parse_semver()

def test_flatten_nested_dict():
    d = {'a': {'b': 1, 'c': {'d': 2}}, 'e': 3}
    assert flatten_nested_dict(d) == {'a.b': 1, 'a.c.d': 2, 'e': 3}
    assert flatten_nested_dict({}) == {}
    assert flatten_nested_dict({'a': 1, 'b': 2}) == {'a': 1, 'b': 2}
    d = {'a': {'b': 1, 'c': {'d': 2}}}
    assert flatten_nested_dict(d, sep='/') == {'a/b': 1, 'a/c/d': 2}
    d = {'a': {'b': {}, 'c': 1}}
    result = flatten_nested_dict(d)
    assert result == {'a.b': {}, 'a.c': 1}
    d = {'a': {'b': {'c': {'d': {'e': 5}}}}}
    assert flatten_nested_dict(d) == {'a.b.c.d.e': 5}
test_flatten_nested_dict()
